float a = 1/(1 + n1.z);
float b = -n1.x*n1.y*a;

// Form a basis
float3 b1 = float3(1 - n1.x*n1.x*a, b, -n1.x);
float3 b2 = float3(b, 1 - n1.y*n1.y*a, -n1.y);
